CREATE TABLE "notes" (
  "id" TEXT PRIMARY KEY,
  "html" TEXT,
  "text" TEXT,
  "firstImage" TEXT,
  "filesCount" INTEGER,
  "bookmarked" INTEGER,
  "pinned" INTEGER,
  "synced" INTEGER,
  "trashed" INTEGER,
  "deleted" INTEGER,
  "highlighted" INTEGER,
  "updatedAt" DOUBLE,
  "createdAt" DOUBLE,
  "syncedAt" DOUBLE,
  "revision" INTEGER,
  "shared" INTEGER,
  "shareId" TEXT,
  "isTemplate" INTEGER,
  "rtl" INTEGER,
  "space" TEXT,
  "title" TEXT,
  "summary" TEXT,
  "hasTodo" INTEGER,
  "noteLinks" TEXT,
  "notebookLinks" TEXT,
  "tagLinks" TEXT,
  "fileIds" TEXT
) WITHOUT ROWID;
CREATE TABLE "notebooks" (
  "id" TEXT PRIMARY KEY,
  "title" TEXT,
  "highlighted" INTEGER,
  "inactive" INTEGER,
  "synced" INTEGER,
  "deleted" INTEGER,
  "locked" INTEGER,
  "cover" TEXT,
  "notes" TEXT,
  "childNotebooks" TEXT,
  "parent" TEXT,
  "revision" INTEGER,
  "sortBy" TEXT,
  "activatedAt" DOUBLE,
  "updatedAt" DOUBLE,
  "createdAt" DOUBLE,
  "syncedAt" DOUBLE,
  "space" TEXT
) WITHOUT ROWID;
CREATE TABLE "lists" (
  "id" TEXT PRIMARY KEY,
  "syncedAt" DOUBLE,
  "synced" INTEGER,
  "deleted" INTEGER,
  "revision" INTEGER,
  "content" TEXT,
  "space" TEXT
) WITHOUT ROWID;
CREATE TABLE "files" (
  "id" TEXT PRIMARY KEY,
  "updatedAt" DOUBLE,
  "createdAt" DOUBLE,
  "syncedAt" DOUBLE,
  "synced" INTEGER,
  "deleted" INTEGER,
  "revision" INTEGER,
  "name" TEXT,
  "version" INTEGER,
  "downloadURL" TEXT,
  "tag" TEXT
) WITHOUT ROWID;
CREATE TABLE "tags" (
  "id" TEXT PRIMARY KEY,
  "title" TEXT,
  "icon" TEXT,
  "notes" TEXT,
  "revision" INTEGER,
  "inactive" INTEGER,
  "synced" INTEGER,
  "deleted" INTEGER,
  "activatedAt" DOUBLE,
  "updatedAt" DOUBLE,
  "createdAt" DOUBLE,
  "syncedAt" DOUBLE,
  "sortBy" TEXT,
  "space" TEXT
) WITHOUT ROWID;
